3	/**
4	 * Decorative field of concentric "listening" arcs — the logo's mark, blown up
5	 * into a background motif (DESIGN_SPEC_V2 §1). Strictly decorative
6	 * (aria-hidden); position with the className (usually absolute, one edge,
7	 * pointer-events-none). At most one per viewport.
8	 */
9	export function ArcField({ className = "" }: { className?: string }) {
10	  // Five arcs sharing the logo's center-dot geometry; the second-outermost is
11	  // amber, the rest teal at whisper opacity.
12	  const radii = [90, 150, 210, 270, 330];
13	  return (
14	    <svg
15	      aria-hidden="true"
16	      viewBox="0 0 480 720"
17	      fill="none"
18	      className={["pointer-events-none select-none", className].join(" ")}
19	    >
20	      <circle cx="60" cy="360" r="7" fill="var(--color-primary)" opacity="0.25" />
21	      {radii.map((r, i) => (
22	        <path
23	          key={r}
24	          d={`M ${60 + r * Math.cos(-1.05)} ${360 + r * Math.sin(-1.05)} A ${r} ${r} 0 0 1 ${60 + r * Math.cos(1.05)} ${360 + r * Math.sin(1.05)}`}
25	          stroke={i === 3 ? "var(--color-accent)" : "var(--color-primary)"}
26	          strokeOpacity={i === 3 ? 0.3 : 0.12}
27	          strokeWidth="2.5"
28	          strokeLinecap="round"
29	        />
30	      ))}
31	    </svg>
32	  );
33	}
