2	import { type LucideIcon } from "lucide-react";
3	
4	type Variant = "primary" | "amber" | "ghost" | "danger" | "quiet";
5	
6	const VARIANTS: Record<Variant, string> = {
7	  primary: "bg-primary text-surface hover:bg-primary-dark border-transparent",
8	  amber: "bg-accent text-surface hover:bg-accent-dark border-transparent",
9	  ghost: "bg-transparent text-primary border-border-strong hover:bg-primary-tint",
10	  danger: "bg-alert text-surface hover:brightness-95 border-transparent",
11	  quiet:
12	    "bg-transparent text-primary underline underline-offset-[3px] hover:text-primary-dark border-transparent min-h-0 px-1.5 py-2",
13	};
14	
15	export interface ButtonProps
16	  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
17	  variant?: Variant;
18	  /** Optional leading icon. Always paired with the button's text label. */
19	  icon?: LucideIcon;
20	  full?: boolean;
21	}
22	
23	/**
24	 * Accessible button primitive. ≥48px tap target, visible focus ring (from
25	 * globals.css), text label always present — never icon-only (see SPEC §10).
26	 * v2: pill silhouette, heavier label, tactile press (scale) feedback.
27	 */
28	export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
29	  function Button(
30	    { variant = "primary", icon: Icon, full, className = "", children, type = "button", ...rest },
31	    ref,
32	  ) {
33	    const isQuiet = variant === "quiet";
34	    return (
35	      <button
36	        ref={ref}
37	        type={type}
38	        className={[
39	          "inline-flex items-center justify-center gap-2.5 whitespace-nowrap rounded-pill border font-body font-extrabold leading-tight",
40	          "text-base transition-[background-color,color,transform,box-shadow] duration-200 ease-[cubic-bezier(0.33,0.1,0.25,1)]",
41	          "active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-60 disabled:active:scale-100",
42	          isQuiet ? "" : "min-h-12 px-6 py-2.5",
43	          full ? "w-full" : "",
44	          VARIANTS[variant],
45	          className,
46	        ]
47	          .filter(Boolean)
48	          .join(" ")}
49	        {...rest}
50	      >
51	        {Icon ? <Icon size={20} strokeWidth={2} aria-hidden="true" /> : null}
52	        {children}
53	      </button>
54	    );
55	  },
