"use client";

import * as React from "react";
import { useActionState } from "react";
import { Heart, Headphones, Check, CircleAlert } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Field, Input } from "@/components/ui/Field";
import { signUpAction, type AuthFormState } from "@/app/(auth)/actions";
import { type SignUpRole } from "@/lib/validation/schemas";
import { t } from "@/lib/i18n";

const ROLE_OPTIONS: {
  value: SignUpRole;
  icon: typeof Heart;
  labelKey: "auth.roleCustomerLabel" | "auth.roleProviderLabel";
  hintKey: "auth.roleCustomerHint" | "auth.roleProviderHint";
}[] = [
  {
    value: "customer",
    icon: Heart,
    labelKey: "auth.roleCustomerLabel",
    hintKey: "auth.roleCustomerHint",
  },
  {
    value: "provider",
    icon: Headphones,
    labelKey: "auth.roleProviderLabel",
    hintKey: "auth.roleProviderHint",
  },
];

export function SignUpForm() {
  const [state, formAction, pending] = useActionState<AuthFormState, FormData>(
    signUpAction,
    {},
  );
  const [role, setRole] = React.useState<SignUpRole>("customer");
  const errors = state.fieldErrors ?? {};

  return (
    <form action={formAction} className="flex flex-col gap-6" noValidate>
      {state.error ? (
        <p
          role="alert"
          className="flex items-start gap-2 rounded-card border-l-4 border-alert bg-alert-tint px-4 py-3 text-base text-ink"
        >
          <CircleAlert
            size={20}
            strokeWidth={2}
            aria-hidden="true"
            className="mt-0.5 flex-none text-alert"
          />
          {state.error}
        </p>
      ) : null}

      <fieldset className="flex flex-col gap-2">
        <legend className="mb-2 text-base font-bold text-ink">
          {t("auth.roleLegend")}
        </legend>
        <div className="grid grid-cols-2 gap-3 max-sm:grid-cols-1">
          {ROLE_OPTIONS.map(({ value, icon: Icon, labelKey, hintKey }) => {
            const selected = role === value;
            return (
              // Big radio tile (≥48px target). Selected = teal fill + check +
              // "Selected" text — never color alone.
              <label
                key={value}
                className={[
                  "relative flex min-h-12 cursor-pointer flex-col gap-1.5 rounded-tile p-5 transition-colors duration-200",
                  "has-[:focus-visible]:shadow-[0_0_0_3px_var(--color-focus)]",
                  selected
                    ? "bg-primary text-surface"
                    : "bg-surface-sunk text-ink hover:bg-primary-tint",
                ].join(" ")}
              >
                <input
                  type="radio"
                  name="role"
                  value={value}
                  checked={selected}
                  onChange={() => setRole(value)}
                  className="sr-only"
                />
                <span className="flex items-center justify-between">
                  <Icon
                    size={24}
                    strokeWidth={2}
                    aria-hidden="true"
                    className={selected ? "text-surface" : "text-primary"}
                  />
                  {selected ? (
                    <span className="inline-flex items-center gap-1.5 text-sm font-bold">
                      <Check size={16} strokeWidth={2.5} aria-hidden="true" />
                      {t("ui.selected")}
                    </span>
                  ) : null}
                </span>
                <span className="text-base font-bold">{t(labelKey)}</span>
                <span
                  className={[
                    "text-sm",
                    selected ? "text-surface" : "text-ink-soft",
                  ].join(" ")}
                >
                  {t(hintKey)}
                </span>
              </label>
            );
          })}
        </div>
      </fieldset>

      <Field
        label={t("auth.fullNameLabel")}
        error={errors.fullName}
        required
      >
        {(props) => (
          <Input
            {...props}
            name="fullName"
            type="text"
            autoComplete="name"
            placeholder={t("auth.fullNamePlaceholder")}
          />
        )}
      </Field>

      <Field label={t("auth.emailLabel")} error={errors.email} required>
        {(props) => (
          <Input
            {...props}
            name="email"
            type="email"
            autoComplete="email"
            placeholder={t("auth.emailPlaceholder")}
          />
        )}
      </Field>

      <Field
        label={t("auth.passwordLabel")}
        hint={t("auth.passwordHint")}
        error={errors.password}
        required
      >
        {(props) => (
          <Input
            {...props}
            name="password"
            type="password"
            autoComplete="new-password"
          />
        )}
      </Field>

      <Button type="submit" full disabled={pending}>
        {pending ? t("ui.loading") : t("auth.submitSignUp")}
      </Button>
    </form>
  );
}

